int *subSort(int *array, int arraySize, int *returnSize) {
  int m = -1, n = -1;
  int max = array[0];
  for (int i = 1; i < arraySize; i++) {
    if (array[i] < max) {
      n = i;
    } else {
      max = array[i];
    }
  }
  int min = array[arraySize - 1];
  for (int i = arraySize - 2; i >= 0; i--) {
    if (array[i] > min) {
      m = i;
    } else {
      min = array[i];
    }
  }
  int *res = (int *)malloc(sizeof(int) * 2);
  res[0] = m;
  res[1] = n;
  *returnSize = 2;
  return res;
}

class Solution {
public:
  vector<int> subSort(vector<int> &array) {
    int m = -1, n = -1;
    int mx = array[0];
    for (int i = 1; i < (int)array.size(); i++) {
      if (array[i] < mx) {
        n = i;
      } else {
        mx = array[i];
      }
    }
    int mn = array.back();
    for (int i = (int)array.size() - 2; i >= 0; i--) {
      if (array[i] > mn) {
        m = i;
      } else {
        mn = array[i];
      }
    }
    return {m, n};
  }
};

