class Solution:
    def subSort(self, array: List[int]) -> List[int]:
        m = n = -1
        mx = array[0]
        for i in range(1, len(array)):
            if array[i] < mx:
                n = i
            else:
                mx = array[i]
        mn = array[-1]
        for i in range(len(array) - 2, -1, -1):
            if array[i] > mn:
                m = i
            else:
                mn = array[i]
        return [m, n]

impl Solution {
  pub fn sub_sort(array: Vec<i32>) -> Vec<i32> {
    let n = array.len();
    let (mut m, mut nn) = (-1i32, -1i32);
    let mut mx = array[0];
    for i in 1..n {
      if array[i] < mx {
        nn = i as i32;
      } else {
        mx = array[i];
      }
    }
    let mut mn = array[n - 1];
    for i in (0..n - 1).rev() {
      if array[i] > mn {
        m = i as i32;
      } else {
        mn = array[i];
      }
    }
    vec![m, nn]
  }
}

const subSort = (arr: number[]): number[] => {
  let m = -1;
  let n = -1;
  let mx = arr[0];
  for (let i = 1; i < arr.length; i++) {
    if (arr[i] < mx) n = i;
    else mx = arr[i];
  }
  let mn = arr[arr.length - 1];
  for (let i = arr.length - 2; i >= 0; i--) {
    if (arr[i] > mn) m = i;
    else mn = arr[i];
  }
  return [m, n];
};
